                    cells.append(' '.join(''.join(t.text or '' for t in pp.iter(W+'t')) for pp in tc.iter(W+'p')).strip())
                out.append(' | '.join(cells))
    open('work/'+p.split('/')[-1].replace('.docx','.txt'),'w').write('\n'.join(out))
EOF
