                    elif r['sig_objects'] == 0:
                        C.append(cand(d['path'], ps[0]['n'], 'signature_check', f"{des}: строка «{r['role']}» ({r['surname']}, {r['date']}) — подпись не найдена как графический объект, проверить визуально",
